			rts
if16_e_go:			lea if16_e, sp
			rts
if18_e_go:			lea if18_e, sp
			rts
if19_e_go:			lea if19_e, sp
			rts

p_summary_c:		; call summary
			clr.w var_summary_md
			move.l sp, p_summary_rs
			lea p_summary, sp
			rts
p_summary_r:		; end of summary
			movea.l p_summary_rs, sp
			rts
p_mainmap_c:		; call mainmap
			clr.w var_mainmap_e
			clr.w var_mainmap_t
			clr.w var_mainmap_top
			clr.w var_mainmap_hs
			clr.w var_mainmap_he
			move.l sp, p_mainmap_rs
			lea p_mainmap, sp
			rts
p_mainmap_r:		; end of mainmap
			movea.l p_mainmap_rs, sp
			rts
p_area_c:		; call area
			movea.l (sp)+, a0		; a
			move.w (a0), var_area_a
			movea.l (sp)+, a0		; b
			move.w (a0), var_area_b
			movea.l (sp)+, a0		; what
			lea var_area_what, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_area_si2_e
p_area_si2:
			move.b (a0)+, (a1)+
			dbeq d1, p_area_si2
			beq p_area_si2_z
p_area_si2_e:
			clr.b (a1)
p_area_si2_z:
			move.l sp, p_area_rs
			lea p_area, sp
			rts
p_area_r:		; end of area
			movea.l p_area_rs, sp
			rts
p_u_c:		; call u
			movea.l (sp)+, a0		; x
			move.w (a0), var_u_x
			clr.l var_u_u
			move.l sp, p_u_rs
			lea p_u, sp
			rts
p_u_r:		; end of u
			movea.l p_u_rs, sp
			rts
p_showptr_c:		; call showptr
			movea.l (sp)+, a0		; what
			lea var_showptr_what, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_showptr_si0_e
p_showptr_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_showptr_si0
			beq p_showptr_si0_z
p_showptr_si0_e:
			clr.b (a1)
p_showptr_si0_z:
			movea.l (sp)+, a0		; p
			move.l (a0), var_showptr_p
			move.l sp, p_showptr_rs
			lea p_showptr, sp
			rts
p_showptr_r:		; end of showptr
			movea.l p_showptr_rs, sp
			rts

